using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using AcxiomCRM.ViewModels;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.AspNetCore.Mvc.Rendering;
namespace AcxiomCRM.Controllers;
public class LeadsController(CrmDb db,CrmService crm,AuditService audit):Controller {
public async Task<IActionResult> Index(string? q,string? status,string? owner,int page=1){var rows=crm.Scope<Lead>();if(!string.IsNullOrWhiteSpace(q))rows=rows.Where(x=>x.LeadName.Contains(q)||x.Email.Contains(q)||x.Phone.Contains(q)||x.CompanyName.Contains(q)||x.Source.Contains(q)||x.Status.Contains(q)||x.Priority.Contains(q));if(!string.IsNullOrEmpty(status))rows=rows.Where(x=>x.Status==status);if(!string.IsNullOrEmpty(owner))rows=rows.Where(x=>x.AssignedTo==owner);page=Math.Clamp(page,1,100000);ViewBag.Page=page;ViewBag.Total=await rows.CountAsync();ViewBag.Q=q;ViewBag.Status=status;ViewBag.Owner=owner;await Options();return View(await rows.OrderByDescending(x=>x.Id).Skip((page-1)*15).Take(15).ToListAsync());}
async Task Options(){ViewBag.Owners=new SelectList(await crm.Owners().OrderBy(x=>x.FullName).ToListAsync(),"Id","FullName");}
public async Task<IActionResult> Details(int id){var e=await crm.Scope<Lead>().FirstOrDefaultAsync(x=>x.Id==id);return e==null?NotFound():View(e);}
public async Task<IActionResult> Create(){await Options();ViewBag.Editing=false;return View("Edit",new LeadInput{AssignedTo=crm.Id});}
public async Task<IActionResult> Edit(int id){var e=await crm.Scope<Lead>().FirstOrDefaultAsync(x=>x.Id==id);if(e==null)return NotFound();await Options();ViewBag.Editing=true;ViewBag.Id=id;return View(LeadInput.From(e));}
[HttpPost] public Task<IActionResult> Create(LeadInput input)=>Save(null,input);
[HttpPost] public Task<IActionResult> Edit(int id,LeadInput input)=>Save(id,input);
async Task<IActionResult> Save(int? id,LeadInput input){var e=id==null?new Lead():await crm.Scope<Lead>().FirstOrDefaultAsync(x=>x.Id==id);if(e==null)return NotFound();var before=id==null?null:LeadInput.From(e);var oldStatus=e.Status;input.Apply(e);e.AssignedTo=input.AssignedTo??(id==null?crm.Id:e.AssignedTo);if(ModelState.IsValid){var error=await crm.Validate(e,id==null?null:oldStatus);if(error!=null)ModelState.AddModelError("",error);}
if(ModelState.IsValid){await using var tx=await db.Database.BeginTransactionAsync();try{if(id==null)db.Add(e);await db.SaveChangesAsync();audit.Add(id==null?"Create":"Update","Lead",e.Id.ToString(),before,LeadInput.From(e));await db.SaveChangesAsync();await tx.CommitAsync();TempData["Message"]="Record saved.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){await tx.RollbackAsync();ModelState.AddModelError("","Could not save: duplicate or invalid related record.");}}
await Options();ViewBag.Editing=id!=null;ViewBag.Id=id;return View("Edit",input);}
[HttpPost] public async Task<IActionResult> Delete(int id){var e=await crm.Scope<Lead>().FirstOrDefaultAsync(x=>x.Id==id);if(e==null)return NotFound();e.IsDeleted=true;audit.Add("Delete","Lead",id.ToString(),LeadInput.From(e));await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
[HttpPost] public async Task<IActionResult> Convert(int id){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var l=await crm.Scope<Lead>().FirstOrDefaultAsync(x=>x.Id==id);if(l==null)return NotFound();if(l.Status!="Qualified"){TempData["Message"]="Only qualified leads can convert.";return RedirectToAction(nameof(Index));}var c=await crm.Scope<Customer>().FirstOrDefaultAsync(x=>x.NormalizedEmail==l.Email.Trim().ToUpper());if(c==null){c=new Customer{CustomerName=l.LeadName,Email=l.Email,Phone=l.Phone,CompanyName=l.CompanyName,AssignedTo=l.AssignedTo,CreatedBy=crm.Id};var error=await crm.Validate(c);if(error!=null){TempData["Message"]=error;return RedirectToAction(nameof(Index));}db.Add(c);await db.SaveChangesAsync();audit.Add("Create","Customer",c.Id.ToString(),after:CustomerInput.From(c));}else if(c.Phone!=l.Phone){TempData["Message"]="Existing customer contact does not match.";return RedirectToAction(nameof(Index));}l.Status="Converted";l.ConvertedCustomerId=c.Id;if(l.ExpectedValue>0){var o=new Opportunity{OpportunityName=l.LeadName+" opportunity",CustomerId=c.Id,LeadId=l.Id,AssignedTo=l.AssignedTo,Amount=l.ExpectedValue,ExpectedCloseDate=DateTime.Today.AddDays(30)};db.Add(o);await db.SaveChangesAsync();audit.Add("Create","Opportunity",o.Id.ToString(),after:OpportunityInput.From(o));}audit.Add("Convert","Lead",l.Id.ToString(),new{Status="Qualified"},LeadInput.From(l));await db.SaveChangesAsync();await tx.CommitAsync();TempData["Message"]="Lead converted.";return RedirectToAction(nameof(Index));}
}
